<?php
declare(strict_types=1); require_once __DIR__.'/bootstrap.php'; require_login(); $pdo=db();
$q=trim((string)($_GET['q']??''));$state=(string)($_GET['state']??'');$component=(int)($_GET['component']??0);$year=(string)($_GET['year']??'');$where=[];$args=[];
if($q!==''){ $where[]='(p.project_code LIKE ? OR p.project_name LIKE ? OR si.code LIKE ? OR si.name LIKE ? OR s.country LIKE ?)';for($i=0;$i<5;$i++)$args[]='%'.$q.'%';}
if(in_array($state,['draft','review','approval','approved'],true)){ $where[]='s.state=?';$args[]=$state; }
if($component){$where[]='c.id=?';$args[]=$component;}
if(ctype_digit($year)){$where[]='s.reporting_year=?';$args[]=(int)$year;}
$sql="SELECT s.*,p.project_code,p.project_name,si.code sub_code,si.name sub_name,c.code component_code,c.name component_name,i.code geb_code,u.name submitter FROM subindicator_submissions s JOIN projects p ON p.id=s.project_id JOIN sub_indicators si ON si.id=s.sub_indicator_id JOIN components c ON c.id=si.component_id LEFT JOIN indicators i ON i.id=s.geb_indicator_id JOIN users u ON u.id=s.submitted_by ".($where?'WHERE '.implode(' AND ',$where):'')." ORDER BY s.updated_at DESC,s.id DESC";$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$components=$pdo->query('SELECT * FROM components WHERE active=1 ORDER BY sort_order')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sub-indicators | ISLANDS</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="app-shell"><?php include __DIR__.'/partials/sidebar.php';?><main class="main"><header class="topbar"><div><div class="eyebrow">RESULTS-BASED INDICATORS</div><h1>Sub-indicator register</h1><p class="muted">Project outcomes and outputs organised under the four framework components.</p></div><a class="btn primary" href="subindicator.php">+ New sub-indicator report</a></header><section class="panel"><div class="panel-head"><div><div class="eyebrow">REGISTER</div><h3>Component and project reporting</h3></div><a class="btn secondary" href="subindicator_export.php?format=csv&amp;q=<?=urlencode($q)?>&amp;state=<?=urlencode($state)?>&amp;component=<?=$component?>&amp;year=<?=urlencode($year)?>">↓ CSV</a></div><form class="filters"><div><label>Search<input name="q" value="<?=e($q)?>" placeholder="Project, sub-indicator, country..."></label></div><div><label>Component<select name="component"><option value="">All components</option><?php foreach($components as $c):?><option value="<?=$c['id']?>" <?=$component===$c['id']?'selected':''?>><?=e($c['code'].' — '.$c['name'])?></option><?php endforeach;?></select></label></div><div><label>Status<select name="state"><option value="">All statuses</option><?php foreach(['draft'=>'Draft','review'=>'Review','approval'=>'Approval','approved'=>'Completed'] as $k=>$v):?><option value="<?=$k?>" <?=$state===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label></div><div><label>Year<input name="year" value="<?=e($year)?>" placeholder="2026"></label></div><button class="btn secondary" type="submit">Filter</button><a class="btn ghost" href="subindicators.php">Reset</a></form><div class="table-wrap"><table class="wide"><thead><tr><th>ID</th><th>Component</th><th>Sub-indicator</th><th>Project</th><th>Linked GEB</th><th>Country</th><th>Value</th><th>Year</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=str_pad((string)$r['id'],5,'0',STR_PAD_LEFT)?></td><td><span class="code"><?=e($r['component_code'])?></span><small><?=e($r['component_name'])?></small></td><td><strong><?=e($r['sub_code'])?></strong><small><?=e($r['sub_name'])?></small></td><td><strong><?=e($r['project_code'])?></strong><small><?=e($r['project_name'])?></small></td><td><?=e($r['geb_code']??'—')?></td><td><?=e($r['country'])?></td><td><?=e($r['reported_value']!==null?(string)$r['reported_value']:'—')?> <?=e($r['unit']??'')?></td><td><?=$r['reporting_year']?></td><td><span class="status <?=e($r['state'])?>"><?=e(workflow_label($r['state']))?></span></td><td><a class="btn small" href="subindicator.php?id=<?=$r['id']?>">Open</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="10" class="empty">No sub-indicator records match your filters.</td></tr><?php endif;?></tbody></table></div></section></main></div></body></html>
